import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第三卷 潮汐 · 第51章 不想见","description":"","frontmatter":{},"headers":[],"relativePath":"第51章_不想见.md","filePath":"第51章_不想见.md"}'),r={name:"第51章_不想见.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第三卷-潮汐-·-第51章-不想见" tabindex="-1">第三卷 潮汐 · 第51章 不想见 <a class="header-anchor" href="#第三卷-潮汐-·-第51章-不想见" aria-label="Permalink to &quot;第三卷 潮汐 · 第51章 不想见&quot;">​</a></h1><p>风是从海边吹过来的，带着咸味和冷意，巷子里的冷气贴着墙根走，后颈一凉。</p><p>冬后的南雾县湿冷得不肯痛快。早上是潮冷，午后太阳出来也不暖，风一阵一阵从操场外的树上刮过来，摇得窗框轻颤。南雾县靠海，雾气散了又聚，潮味裹着寒气，阳光落下来也只是白茫茫一片。我站在小巷口，手插在口袋里，捏着一颗海盐糖，糖纸被手汗洇得发软，没有拆，指腹把纸角捻得发皱。</p><p>江苒的消息很短。她说最近不想见了，想一个人待一阵，语气很平，像怕惊动什么。</p><p>我盯着那行字看了很久，久到巷口水果摊的橘子清香飘过来，混着海风的咸，混着风刮铁皮的声音，鼻子发酸。摊主把橘子剥开，汁水溅出来，鲜亮的香。我回了一个字，好。手指按下去很稳，像按在一个无声的鼓面上，心里却空了一块，像潮水退后露出的沙，湿凉一片。</p><p>回到教室，午休还没散。风扇转得慢，吹不动热气，窗台的玻璃罐被太阳晒得发烫。阳光斜照在桌角的玻璃罐上，里面挤满纸星星。粉的黄的蓝的，都是江苒叠的。她叠的时候指尖翻飞，纸张发出细碎的响，指节会发白，折痕压得很深。她说难过时叠一颗，心会安静些，像把乱线一根根理好。</p><p>我拿起一颗放在掌心，纸面粗糙，棱角硌得皮肤发痒，指尖的汗让纸面有点潮。</p><p>陈默拍了拍我的椅背，手里捧着一杯热水，热气扑上来，低声问脸色怎么这么差。我摇头说没事，把星星放回去，盖子拧紧，玻璃轻响。他把热水杯推过来，白气升起来，带着温热的水气，杯壁烫手。我喝了一口，喉咙一烫，暖意往下走，却压不住心慌，汗从额头又冒出来。</p><p>那种慌很具体，像站在退潮的海边，看水一点点后退，露出湿冷的沙。你知道水会回来，可脚底发凉，不知道要等多久，不知道那条水线会退到哪里。</p><p>下午是叶老师的课。她在黑板上写字，粉笔灰簌簌地落，落在讲台沿上。她声音温和，讲潮汐，说月亮牵着海水，人站在岸上，总以为能决定进退，其实多半被推着走，话里带着笑。窗玻璃被晒得发烫，我用指尖划了一下，薄汗透进来，凉意一闪又被暑气盖住。我听得走神，蝉鸣贴着窗缝往里钻，一声接一声。</p><p>江苒坐在斜前方，扎着低马尾，露出后颈一小截皮肤，后颈也挂着细汗。她一直没回头，背挺得很直，笔动得很快，像怕一停就会想起什么，笔尖划纸的声响又快又轻。</p><p>下课铃响，教室吵起来，风扇的风把纸张吹得翻起。林小满抱着作业本跑来，发丝沾着细小的汗珠，眼睛亮亮的，气息有点急。她问我，江苒中午没吃饭，你见过她了吗，声音压得很低。我顿了一下，说她说最近不想见。林小满啊了一声，本子差点掉下来，又看看江苒的背影，声音小下去，那你怎么回的。我说回了个好字，纸星星在口袋里硌了一下。她瞪我，就一个好字，你就这么答应了。我点头，口袋里的糖纸被捏出细小的脆响，指甲都陷进纸里。</p><p>那颗海盐糖是宋阿婆给的。她说心慌时含一颗，咸先出来，甜后出来，忍一忍就过去，热天含一颗也压得住蝉鸣。可我现在连拆开的力气都没有，手指都是软的。</p><p>林小满叹气，说你嘴上答应得倒快，答应完脸都白了。她把本子塞给我，让我帮着抱去办公室，自己去找江苒了，脚步很快，带起一阵风。</p><p>我抱着那摞本子走在走廊上。纸边蹭着手腕，有点疼，有点热。风从尽头窗口灌进来，带着暑气的闷和海潮的咸，吹在汗湿的皮肤上，黏黏的。</p><p>放学时天已暗下来，蝉鸣低了，暑气却没散。</p><p>我沿海边小路往回走。潮水声一下一下拍着石头，空气咸而湿，汗在衣领里潮了一圈。我终于拆开那颗糖，糖纸发粘，剥时轻响，粘在指尖。糖进嘴先是咸，咸得皱眉，舌尖发麻，之后才渗出很淡的甜，要很仔细才尝得到，甜味被海风一吹就淡了。</p><p>我想起江苒叠星星的样子。她说最难的是收尾，小角要塞进去，不能露出来，不然不好看，也容易散。我当时笑她太要强，连颗星星都不许散。她也笑，眼睛弯起来，有光。现在想起，心口像被小角扎了一下，又痒又疼。</p><p>手机震了一下，是江苒。她问，叶老师讲的潮汐，你听了吗，课上都没见你抬头。我说听了，讲月亮牵着海。她说她觉得说得不对，人也不全是被推着走，有时是自己想退一下，退一下才能看清。</p><p>我站在风里看灰白的海面。浪翻起来碎成白沫，又退下去，沙滩留下一道深色水线，很快又被新浪盖住，蝉鸣从岸边的树上传来，和浪声撞在一起。我打字很慢，一个字一个字按，拇指上全是汗，屏幕都花了。我说好，那我等你想见的时候。发出去后热气灌进脖子，汗顺着后颈往下淌，我把外套脱下来搭在臂弯，嘴里甜味停了一会儿，又被咸盖过去。她没再回，屏幕暗下去，只剩潮声。</p><p>我把糖纸叠小塞进口袋，摸到几颗她之前塞给我的纸星星，纸角扎手，硬硬的，带着她的手温。抬头看天，暑气蒸得天色发白，看不到月亮。可我知道它在那里，牵着这片海，一起一伏。就像她牵着我，我却不敢用力，怕一用力线就断了。</p><p>回家放下书包，屋里闷热，风扇转着，吹不散潮。桌上放着半个橘子，皮还新鲜，是奶奶留的。我拿起橘子剥开，汁水沾在指尖，清香驱散一点闷，塞一瓣进嘴，酸甜在舌尖跳了一下。我拿出那盘旧的课文录音带，外壳有点裂，标签上是她小小的字，写着给退潮时听，字迹被手汗洇得有点淡。我把它放进抽屉的旧录音机里，按下播放键，咔哒一声，带子转动的轻响混着电流杂音流出来，她的哼唱很轻，像从很远飘来，被蝉鸣垫在底下。</p><p>我坐在桌前，把那颗纸星星拿出来，放在掌心一遍遍转，纸角硌手。我想起上次她发烧时，我把热水递过去，她捧着杯子说烫，却不肯放手，热气熏得她眼睛都湿了。那时我以为握紧杯子就是靠近，现在才明白，有时松开一点，才不会烫伤。</p><p>眼眶发热，明明说了好，心里慌得不行，怕她这一退，就退到我够不到的地方。风扇的风把信纸吹得轻晃，我站起来把窗关小，让蝉鸣轻一点。</p><p>我在桌边把热水壶拿起，倒一杯热水，热气扑在脸上，烫得眼角都湿了。我把热水捧在手心，一口一口喝，喝到出汗，汗顺着额头往下淌，滴在星星上，纸面洇出深色小点。我又拿热毛巾擦脸，毛巾湿热，贴在皮肤上，像把慌压回去一点。擦完把毛巾拧干，水拧进盆里，哗啦轻响。</p><p>做完这些，屋里安静下来，只有带子转动的沙沙声。我躺到床上，枕边放着那罐星星，玻璃被暑气烘得温热，手搭在罐身上，听着自己的心跳，和带子里她的呼吸混在一起。</p><p>我对自己说，好，就等，等她想见。嘴上这么说，心里却像潮水被风顶住，进也不得，退也不得，整晚都绷在那里。</p><p>就在这时，带子那头忽然停了半拍，接着传来她留的一句很轻的话，像在耳边叹气，我一下坐直，把音量拧到最大，热气和心跳一起撞上来。</p>',28)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
